    public static bool Handles(string kind) { return kind=="resource.sprites"||kind=="resource.atlas"||kind=="resource.font"||kind=="resource.spine"||kind=="resource.import"||kind=="resource.project-settings"||kind=="resource.serialized-asset"; }
    public static void Apply(string kind,string payloadJson) {
