        if(type==null)throw new Exception("Sprite Data Provider companion is not installed for this resource.sprites transaction");
        var target=type.GetMethod(method,BindingFlags.Public|BindingFlags.Static);if(target==null)throw new Exception("Sprite Data Provider companion method unavailable: "+method);
        try{target.Invoke(null,args);}catch(TargetInvocationException e){throw e.InnerException??e;}
