    static string[] CanonicalPackedCloneNames(string[] clonedNames,string[] expectedNames) { if(expectedNames.GroupBy(x=>x,StringComparer.Ordinal).Any(g=>g.Count()!=1))throw new Exception("Packed Sprite name readback is ambiguous because source names are duplicated");var canonical=new List<string>();foreach(var clone in clonedNames){var matches=expectedNames.Where(source=>String.Equals(clone,source,StringComparison.Ordinal)||String.Equals(clone,source+"(Clone)",StringComparison.Ordinal)).ToArray();if(matches.Length!=1)throw new Exception("Packed Sprite clone name does not map uniquely to one source Sprite: "+clone);canonical.Add(matches[0]);}return canonical.OrderBy(x=>x,StringComparer.Ordinal).ToArray(); }
